import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";
import { redirect } from "next/navigation";
import Link from "next/link";
import { db } from "@/lib/db";

export default async function InvestmentsPage() {
  const session = await getServerSession(authOptions);

  if (!session) {
    redirect("/login");
  }

  const user = session.user as any;

  // Fetch active investment plans and user investments
  const plans = await db.investmentPlan.findMany({
    where: { active: true },
  });

  const dbUser = await db.user.findUnique({
    where: { email: user.email },
    include: {
      investments: {
        include: { plan: true },
        orderBy: { createdAt: "desc" },
      },
    },
  });

  const userInvestments = dbUser?.investments || [];

  return (
    <div className="min-h-screen bg-slate-950 text-slate-100 flex">
      {/* Sidebar */}
      <aside className="w-64 bg-slate-900 border-r border-slate-800 flex flex-col hidden md:flex">
        <div className="p-6 border-b border-slate-800">
          <h1 className="text-xl font-bold tracking-wider text-indigo-400">CivicBank</h1>
          <p className="text-xs text-slate-400 mt-1">Secure Enterprise Portal</p>
        </div>

        <nav className="flex-1 p-4 space-y-2">
          <Link
            href="/dashboard"
            className="flex items-center space-x-3 px-4 py-2.5 rounded-lg text-slate-400 hover:bg-slate-800 hover:text-slate-200 font-medium text-sm transition-colors"
          >
            <span>📊</span>
            <span>Dashboard</span>
          </Link>
          <Link
            href="/dashboard/transactions"
            className="flex items-center space-x-3 px-4 py-2.5 rounded-lg text-slate-400 hover:bg-slate-800 hover:text-slate-200 font-medium text-sm transition-colors"
          >
            <span>💸</span>
            <span>Transactions</span>
          </Link>
          <Link
            href="/dashboard/investments"
            className="flex items-center space-x-3 px-4 py-2.5 rounded-lg bg-indigo-600/10 text-indigo-400 font-medium text-sm transition-colors"
          >
            <span>📈</span>
            <span>Investments</span>
          </Link>
          <Link
            href="/dashboard/settings"
            className="flex items-center space-x-3 px-4 py-2.5 rounded-lg text-slate-400 hover:bg-slate-800 hover:text-slate-200 font-medium text-sm transition-colors"
          >
            <span>⚙️</span>
            <span>Settings</span>
          </Link>
        </nav>

        <div className="p-4 border-t border-slate-800">
          <Link
            href="/api/auth/signout"
            className="w-full flex items-center justify-center space-x-2 bg-red-500/10 hover:bg-red-500/20 text-red-400 py-2 rounded-lg text-sm font-medium transition-colors border border-red-500/20"
          >
            <span>Sign Out</span>
          </Link>
        </div>
      </aside>

      {/* Main Content Area */}
      <main className="flex-1 flex flex-col min-w-0 overflow-y-auto">
        <header className="bg-slate-900 border-b border-slate-800 h-16 flex items-center justify-between px-6 sticky top-0 z-10">
          <h2 className="text-lg font-semibold text-slate-200">Investment Portfolios</h2>
          <span className="text-xs bg-indigo-500/10 text-indigo-400 border border-indigo-500/20 px-3 py-1 rounded-full font-medium">
            Active Vaults
          </span>
        </header>

        <div className="p-6 space-y-8 max-w-7xl w-full mx-auto">
          {/* Available Plans Section */}
          <div>
            <h3 className="text-base font-semibold text-slate-200 mb-4">Available Investment Plans</h3>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              {plans.length > 0 ? (
                plans.map((plan) => (
                  <div key={plan.id} className="bg-slate-900 border border-slate-800 p-6 rounded-xl shadow-lg flex flex-col justify-between">
                    <div>
                      <h4 className="text-lg font-bold text-white">{plan.name}</h4>
                      <p className="text-xs text-slate-400 mt-1">{plan.description}</p>
                      <div className="mt-4 space-y-2">
                        <div className="flex justify-between text-sm">
                          <span className="text-slate-400">Expected Return:</span>
                          <span className="font-semibold text-emerald-400">{plan.expectedReturn}</span>
                        </div>
                        <div className="flex justify-between text-sm">
                          <span className="text-slate-400">Min. Deposit:</span>
                          <span className="font-semibold text-white">${Number(plan.minimumAmount).toFixed(2)}</span>
                        </div>
                        <div className="flex justify-between text-sm">
                          <span className="text-slate-400">Duration:</span>
                          <span className="font-semibold text-slate-200">{plan.durationDays} Days</span>
                        </div>
                      </div>
                    </div>
                    <button className="mt-6 w-full py-2.5 bg-indigo-600 hover:bg-indigo-700 text-white font-medium rounded-lg text-sm transition-colors">
                      Invest Now
                    </button>
                  </div>
                ))
              ) : (
                <div className="col-span-3 bg-slate-900 border border-slate-800 p-8 rounded-xl text-center text-slate-500">
                  No investment plans currently available. Check back soon.
                </div>
              )}
            </div>
          </div>

          {/* User Active Investments History */}
          <div className="bg-slate-900 border border-slate-800 rounded-xl shadow-lg overflow-hidden">
            <div className="p-6 border-b border-slate-800">
              <h3 className="text-base font-semibold text-slate-200">Your Active Portfolio History</h3>
            </div>
            <div className="overflow-x-auto">
              <table className="w-full text-left border-collapse">
                <thead>
                  <tr className="bg-slate-950/50 text-slate-400 text-xs uppercase tracking-wider border-b border-slate-800">
                    <th className="py-3 px-6">Plan Name</th>
                    <th className="py-3 px-6">Amount Invested</th>
                    <th className="py-3 px-6">Status</th>
                    <th className="py-3 px-6">Payment Status</th>
                    <th className="py-3 px-6">Date</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-800 text-sm text-slate-300">
                  {userInvestments.length > 0 ? (
                    userInvestments.map((inv: any) => (
                      <tr key={inv.id} className="hover:bg-slate-800/50 transition-colors">
                        <td className="py-4 px-6 font-medium text-white">{inv.plan?.name || "Custom Plan"}</td>
                        <td className="py-4 px-6 font-semibold text-indigo-400">${Number(inv.amount).toFixed(2)}</td>
                        <td className="py-4 px-6">
                          <span className="px-2.5 py-1 text-xs rounded-full font-medium bg-sky-500/10 text-sky-400 border border-sky-500/20">
                            {inv.status}
                          </span>
                        </td>
                        <td className="py-4 px-6">
                          <span className="px-2.5 py-1 text-xs rounded-full font-medium bg-amber-500/10 text-amber-400 border border-amber-500/20">
                            {inv.paymentStatus}
                          </span>
                        </td>
                        <td className="py-4 px-6 text-slate-400 text-xs">
                          {new Date(inv.createdAt).toLocaleDateString()}
                        </td>
                      </tr>
                    ))
                  ) : (
                    <tr>
                      <td colSpan={5} className="py-8 text-center text-slate-500 text-sm">
                        You have not placed any investments yet.
                      </td>
                    </tr>
                  )}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      </main>
    </div>
  );
}